230	  /// loaded message's persisted `streaming` status — a message restored
231	  /// from history/cache can legitimately carry that status without a
232	  /// send actually being in flight (I/O matrix: mid-stream drop).
233	  Future<void> sendMessage(String content) async {
234	    final trimmed = content.trim();
235	    if (trimmed.isEmpty) {
236	      return;
237	    }
238	    final current = state;
239	    if (current is! ChatReady) {
240	      return;
241	    }
242	    if (_isSending) {
243	      return;
244	    }
245	    _isSending = true;
246	
247	    final userMessage = ChatUiMessage(
248	      id: _nextLocalId(),
249	      role: ChatMessageRole.user,
250	      content: trimmed,
251	      status: ChatMessageStatus.complete,
252	    );
253	    final aiMessage = ChatUiMessage(
254	      id: _nextLocalId(),
255	      role: ChatMessageRole.assistant,
256	      content: '',
257	      status: ChatMessageStatus.streaming,
258	    );
259	    emit(
260	      current.copyWith(
261	        messages: [...current.messages, userMessage, aiMessage],
262	        isSending: true,
263	      ),
264	    );
265	
266	    await _sendSubscription?.cancel();
267	    final completer = Completer<void>();
268	    _sendCompleter = completer;
269	    _sendSubscription = _repository
270	        .sendMessage(current.sessionId, trimmed)
271	        .listen(
272	          (event) {
273	            event.match(
274	              (failure) => _markFailed(aiMessage.id),
275	              (streamEvent) => _applyStreamEvent(aiMessage.id, streamEvent),
276	            );
277	          },
278	          onError: (Object _, StackTrace _) {
279	            // RNF09: no exception escapes the cubit — a stream-level
280	            // error (shouldn't happen, `ChatRemoteDataSource.sendMessage`
281	            // never lets one through unmapped) still only fails the
282	            // bubble, never crashes.
283	            _markFailed(aiMessage.id);
284	            _finishSending();
285	            if (!completer.isCompleted) {
286	              completer.complete();
287	            }
288	            _sendCompleter = null;
289	          },
290	          onDone: () {
291	            _finishSending();
292	            if (!completer.isCompleted) {
293	              completer.complete();
294	            }
295	            _sendCompleter = null;
296	          },
297	          cancelOnError: false,
298	        );
299	    await completer.future;
300	  }
