302	  /// Clears both the internal re-entrancy guard and the UI-facing
303	  /// [ChatReady.isSending] signal once a send's stream has ended (`done`,
304	  /// an in-band error, or a stream-level error) — the single place both
305	  /// flip back together.
306	  void _finishSending() {
307	    _isSending = false;
308	    if (isClosed) {
309	      return;
310	    }
311	    final current = state;
312	    if (current is ChatReady) {
313	      emit(current.copyWith(isSending: false));
314	    }
315	  }
316	
317	  void _applyStreamEvent(String aiMessageId, ChatStreamEvent event) {
318	    if (isClosed) {
319	      return;
320	    }
321	    final current = state;
322	    if (current is! ChatReady) {
323	      return;
324	    }
325	    switch (event) {
326	      case ChatMessageCreatedEvent():
327	        // Design Notes: the persisted *user*-message id — no UI-facing
328	        // use yet in this story (Story 6.3's retry call is the first
329	        // consumer).
330	        break;
331	      case ChatTokenEvent(delta: final delta):
332	        emit(
333	          current.copyWith(
334	            messages: [
335	              for (final message in current.messages)
336	                if (message.id == aiMessageId)
337	                  message.copyWith(content: message.content + delta)
338	                else
339	                  message,
340	            ],
341	          ),
342	        );
343	      case ChatDoneEvent():
344	        emit(
345	          current.copyWith(
346	            messages: [
347	              for (final message in current.messages)
348	                if (message.id == aiMessageId)
349	                  message.copyWith(status: ChatMessageStatus.complete)
350	                else
351	                  message,
352	            ],
353	          ),
354	        );
355	    }
356	  }
357	
358	  /// I/O matrix: "Mid-stream drop"/"In-band `error` event" — marks the one
359	  /// bubble `failed`, by id, leaving its already-streamed-in text exactly
360	  /// as-is (never cleared, Boundaries).
361	  void _markFailed(String aiMessageId) {
362	    if (isClosed) {
363	      return;
364	    }
365	    final current = state;
366	    if (current is! ChatReady) {
367	      return;
368	    }
369	    emit(
370	      current.copyWith(
371	        messages: [
372	          for (final message in current.messages)
373	            if (message.id == aiMessageId)
374	              message.copyWith(status: ChatMessageStatus.failed)
375	            else
376	              message,
377	        ],
378	      ),
379	    );
380	  }
