382	  String _nextLocalId() => 'local-${_localIdCounter++}';
383	
384	  @override
385	  Future<void> close() {
386	    _sendSubscription?.cancel();
387	    final completer = _sendCompleter;
388	    if (completer != null && !completer.isCompleted) {
389	      completer.complete();
390	    }
391	    _sendCompleter = null;
392	    return super.close();
393	  }
394	}
